88	/// Classify a `fallback_credit_token` rejection from a 400 body, mirroring
89	/// 2.1.177's `credit_*` outcome labels (cli.js ~511847).
90	pub fn classify_fallback_credit_reject(body: &str) -> Option<&'static str> {
91	    if body.contains("fallback_credit_token: invalid or malformed") {
92	        Some("credit_malformed")
93	    } else if body.contains("fallback_credit_token: does not belong to this organization") {
94	        Some("credit_wrong_org")
95	    } else if body.contains("fallback_credit_token: has expired") {
96	        Some("credit_expired")
97	    } else if body.contains("fallback_credit_token: is not valid for model") {
98	        Some("credit_invalid_model")
99	    } else if body.contains("Extra inputs are not permitted")
100	        && body.contains("fallback_credit_token")
101	    {
102	        Some("credit_extra_forbidden")
103	    } else if body.contains("fallback_credit_token") {
104	        Some("credit_other")
105	    } else {
106	        None
107	    }
108	}
