116	/// Classify a failed Anthropic request and, if a recovery applies, mutate
117	/// `body` in place and return [`RecoveryAction::Retry`]. `latches` carries the
118	/// per-turn sticky flags so each recovery fires at most once.
119	///
120	/// `status` is the HTTP status code; `body` the raw error response text;
121	/// `request_body` the JSON request that was sent (mutated in place on retry).
122	pub fn classify_and_recover(
123	    status: u16,
124	    body: &str,
125	    request_body: &mut Value,
126	    latches: &mut RecoveryLatches,
127	) -> RecoveryAction {
128	    if !is_400(status) {
129	        return RecoveryAction::Surface;
130	    }
131	
132	    // 0. Fallback-credit-token reject — strip the poisoned credit token and
133	    //    retry without it. Highest priority: a bad token fails every retry.
134	    if !latches.fallback_credit_stripped
135	        && let Some(reason) = classify_fallback_credit_reject(body)
136	        && strip_fallback_credit_token(request_body)
137	    {
138	        latches.fallback_credit_stripped = true;
139	        tracing::warn!(
140	            target: "jfc::provider::anthropic_recovery",
141	            reason,
142	            "tengu_fallback_credit_forfeited: server rejected fallback_credit_token — stripping and retrying"
143	        );
144	        return RecoveryAction::Retry(RetryKind::FallbackCreditStrip);
145	    }
146	
147	    // 1. Media-block strip — a 400 pointing at an unprocessable image/document.
148	    if !latches.media_strip_done
149	        && latches.media_blocks_stripped < MAX_MEDIA_BLOCK_STRIPS
150	        && let Some(kind) = detect_unprocessable_media(body)
151	        && strip_first_media_block(request_body, kind)
152	    {
153	        latches.media_blocks_stripped += 1;
154	        if latches.media_blocks_stripped >= MAX_MEDIA_BLOCK_STRIPS {
155	            latches.media_strip_done = true;
156	        }
157	        return RecoveryAction::Retry(RetryKind::MediaStrip);
158	    }
159	
160	    // 2. Cache-diagnosis beta reject — drop the diagnostics field + latch.
161	    if !latches.cache_diagnosis_dropped
162	        && is_cache_diagnosis_beta_reject(body)
163	        && drop_cache_diagnosis(request_body)
164	    {
165	        latches.cache_diagnosis_dropped = true;
166	        return RecoveryAction::Retry(RetryKind::CacheDiagnosisBeta);
167	    }
168	
169	    // 3. Thinking-type toggle — flip enabled↔adaptive.
170	    if !latches.thinking_type_toggled
171	        && is_thinking_type_reject(body)
172	        && toggle_thinking_type(request_body)
173	    {
174	        latches.thinking_type_toggled = true;
175	        return RecoveryAction::Retry(RetryKind::ThinkingType);
176	    }
177	
178	    // 4. Thinking-signature strip — drop ALL thinking blocks.
179	    if !latches.thinking_signature_stripped
180	        && is_thinking_signature_reject(body)
181	        && strip_thinking_blocks(request_body)
182	    {
183	        latches.thinking_signature_stripped = true;
184	        return RecoveryAction::Retry(RetryKind::ThinkingSignatureStrip);
185	    }
186	
187	    // 5. Mid-conversation system fallback — server rejected a `role:"system"`
188	    //    message; fold it into a `<system-reminder>` user block.
189	    if !latches.mid_conv_system_fallback_done
190	        && is_mid_conv_system_reject(body)
191	        && fold_system_role_messages(request_body)
192	    {
193	        latches.mid_conv_system_fallback_done = true;
194	        return RecoveryAction::Retry(RetryKind::MidConvSystem);
195	    }
196	
197	    RecoveryAction::Surface
198	}
