488	/// Settings files in precedence order, each tagged with whether it is
489	/// repository-controlled (`true`) or user-level (`false`).
490	fn settings_sources(project_root: &Path) -> Vec<(PathBuf, bool)> {
491	    let mut sources = Vec::new();
492	    if let Some(home) = dirs::home_dir() {
493	        sources.push((home.join(".claude").join("settings.json"), false));
494	    }
495	    sources.push((project_root.join(".claude").join("settings.json"), true));
496	    sources.push((
497	        project_root.join(".claude").join("settings.local.json"),
498	        true,
499	    ));
500	    sources
501	}
