503	/// CS-JFC-006: whether repo-local `.claude` shell hooks may be activated.
504	///
505	/// Repository-controlled config must not gain shell execution before the user
506	/// has trusted the project. The only trust signal we honor comes from *outside*
507	/// the repository (an environment opt-in), so a malicious checkout cannot
508	/// self-trust by shipping a marker file.
509	pub fn project_hooks_trusted() -> bool {
510	    std::env::var("JFC_TRUST_PROJECT_HOOKS")
511	        .ok()
512	        .is_some_and(|v| !v.is_empty() && v != "0" && !v.eq_ignore_ascii_case("false"))
513	}
