515	pub fn load_merged(project_root: &Path) -> ClaudeCompatibilityConfig {
516	    let trust_project_hooks = project_hooks_trusted();
517	    let mut merged = ClaudeCompatibilityConfig::default();
518	    for (path, is_project) in settings_sources(project_root) {
519	        let Ok(raw) = std::fs::read_to_string(&path) else {
520	            continue;
521	        };
522	        match serde_json::from_str::<ClaudeCompatibilityConfig>(&raw) {
523	            Ok(mut settings) => {
524	                // Never auto-activate repository-controlled shell hooks. A
525	                // project `.claude/settings*.json` that ships hooks would
526	                // otherwise reach `sh -c` on setup/prompt events before the
527	                // user has trusted the project.
528	                if is_project && !trust_project_hooks && settings.hooks.is_some() {
529	                    tracing::warn!(
530	                        target: "jfc::config::claude_settings",
531	                        path = %path.display(),
532	                        "ignoring repo-local .claude shell hooks for an untrusted project; \
533	                         set JFC_TRUST_PROJECT_HOOKS=1 to enable them"
534	                    );
535	                    settings.hooks = None;
536	                }
537	                merged.merge_from(settings);
538	            }
539	            Err(error) => {
540	                tracing::warn!(
541	                    target: "jfc::config::claude_settings",
542	                    path = %path.display(),
543	                    error = %error,
544	                    "failed to parse Claude settings JSON - ignoring"
545	                );
546	            }
547	        }
548	    }
549	    merged
550	}
