557	pub fn apply_settings(cfg: &mut Config, settings: ClaudeCompatibilityConfig) {
558	    if settings.is_empty() && !chrome_mcp_auto_enable_enabled(&settings) {
559	        return;
560	    }
561	
562	    if let Some(model) = settings
563	        .model
564	        .as_ref()
565	        .filter(|model| !model.trim().is_empty())
566	    {
567	        cfg.default.model = Some(model.trim().to_owned());
568	    }
569	    if let Some(fallback_model) = settings
570	        .fallback_model
571	        .as_ref()
572	        .filter(|model| !model.trim().is_empty())
573	    {
574	        let fallback = FallbackModel::Simple(fallback_model.trim().to_owned());
575	        if !cfg
576	            .default
577	            .fallback_models
578	            .iter()
579	            .any(|existing| existing.model_id() == fallback_model.trim())
580	        {
581	            cfg.default.fallback_models.push(fallback);
582	        }
583	        cfg.refusal_fallback_model = Some(fallback_model.trim().to_owned());
584	    }
585	    if cfg.theme.is_none()
586	        && let Some(theme) = settings
587	            .theme
588	            .as_ref()
589	            .filter(|theme| !theme.trim().is_empty())
590	    {
591	        cfg.theme = Some(theme.trim().to_owned());
592	    }
593	    if cfg.output_style.is_none()
594	        && let Some(output_style) = settings
595	            .output_style
596	            .as_ref()
597	            .filter(|style| !style.trim().is_empty())
598	    {
599	        cfg.output_style = Some(output_style.trim().to_owned());
600	    }
601	    if let Some(shell) = settings
602	        .default_shell
603	        .as_ref()
604	        .filter(|shell| !shell.trim().is_empty())
605	    {
606	        cfg.default_shell = Some(shell.trim().to_owned());
607	    }
608	    if let Some(always_thinking) = settings.always_thinking_enabled {
609	        cfg.default.provider_options.insert(
610	            "alwaysThinkingEnabled".to_owned(),
611	            serde_json::Value::Bool(always_thinking),
612	        );
613	    }
614	    if let Some(thinking_budget) = settings.thinking_budget {
615	        cfg.default.thinking_budget = Some(thinking_budget);
616	    }
617	    if let Some(thinking_display) = settings
618	        .thinking_display
619	        .as_ref()
620	        .filter(|display| !display.trim().is_empty())
621	    {
622	        cfg.default.provider_options.insert(
623	            "thinkingDisplay".to_owned(),
624	            serde_json::Value::String(thinking_display.trim().to_owned()),
625	        );
626	    }
627	    if let Some(mode) = settings
628	        .permissions
629	        .default_mode
630	        .as_deref()
631	        .and_then(normalize_permission_mode)
632	    {
633	        cfg.default
634	            .permission
635	            .insert("mode".to_owned(), mode.to_owned());
636	    }
637	    if !settings.permissions.allow.is_empty() || !settings.permissions.deny.is_empty() {
638	        let automation = cfg
639	            .permission_automation
640	            .get_or_insert_with(PermissionAutomationConfig::default);
641	        automation.enabled = true;
642	        extend_unique(
643	            &mut automation.allowed_tools,
644	            settings.permissions.allow.clone(),
645	        );
646	        extend_unique(
647	            &mut automation.denied_tools,
648	            settings.permissions.deny.clone(),
649	        );
650	    }
651	    if let Some(hooks) = settings.hooks.clone() {
652	        cfg.hooks = merge_hooks(cfg.hooks.take(), Some(hooks));
653	    }
654	    if settings.disable_all_hooks == Some(true) {
655	        cfg.hooks = None;
656	    }
657	    for (name, server) in &settings.mcp_servers {
658	        cfg.mcp.insert(name.clone(), server.clone());
659	    }
660	    apply_chrome_mcp_auto_enable(cfg, &settings);
661	    if let Some(worktree) = settings.worktree.clone() {
662	        cfg.worktree = merge_worktree(cfg.worktree.take(), Some(worktree));
663	    }
664	    if let Some(sandbox) = settings.sandbox.clone() {
665	        cfg.sandbox = merge_sandbox(cfg.sandbox.take(), Some(sandbox));
666	    }
667	    if settings.disable_remote_control == Some(true) {
668	        cfg.remote_control
669	            .get_or_insert_with(RemoteControlConfig::default)
670	            .disabled = true;
671	    }
672	    if settings.disable_agent_view == Some(true) {
673	        cfg.disabled_tools.push("AgentView".to_owned());
674	    }
675	    if settings.disable_workflows == Some(true) && settings.enable_workflows != Some(true) {
676	        cfg.disabled_tools.push("Workflow".to_owned());
677	    }
678	
679	    // Compaction settings — bridge into Config's own fields
680	    if let Some(enabled) = settings.auto_compact_enabled {
681	        cfg.auto_compact_enabled = enabled;
682	    }
683	    if let Some(window) = settings.auto_compact_window {
684	        cfg.auto_compact_window = Some(window);
685	    }
686	
687	    // Memory recall — autoMemoryEnabled gates memory_recall_enabled.
688	    if let Some(enabled) = settings.auto_memory_enabled {
689	        cfg.memory_recall_enabled = enabled;
690	    }
691	
692	    // Effort level → reasoning_effort + thinking budget mapping.
693	    // CC 2.1.167 maps effortLevel to the model's reasoning effort level.
694	    if let Some(ref level) = settings.effort_level {
695	        let effort_str = match level.trim() {
696	            "low" => Some("low"),
697	            "medium" => Some("medium"),
698	            "high" => Some("high"),
699	            "max" | "xhigh" => Some("max"),
700	            _ => None,
701	        };
702	        if let Some(e) = effort_str {
703	            if cfg.default.reasoning_effort.is_none() {
704	                cfg.default.reasoning_effort = Some(e.to_owned());
705	            }
706	        }
707	        // Also set thinking budget as a fallback for providers that use it.
708	        let budget = match level.trim() {
709	            "low" => Some(1_000u32),
710	            "medium" => Some(5_000u32),
711	            "high" => Some(10_000u32),
712	            "max" | "xhigh" => Some(32_000u32),
713	            _ => None,
714	        };
715	        if let Some(b) = budget {
716	            cfg.default.thinking_budget = cfg.default.thinking_budget.or(Some(b));
717	        }
718	        // "max"/"xhigh" → ultracode
719	        if matches!(level.trim(), "max" | "xhigh") && cfg.default.ultracode.is_none() {
720	            cfg.default.ultracode = Some(true);
721	        }
722	    }
723	
724	    cfg.claude = settings;
725	}
