7	pub enum ContentBlock {
8	    Text {
9	        #[allow(dead_code)]
10	        text: String,
11	    },
12	    Thinking {
13	        #[allow(dead_code)]
14	        thinking: String,
15	    },
16	    /// Server-redacted thinking block — opaque base64 blob, no deltas.
17	    /// Must be round-tripped verbatim in subsequent requests.
18	    RedactedThinking {
19	        data: String,
20	    },
21	    ToolUse {
22	        id: String,
23	        name: String,
24	        #[allow(dead_code)]
25	        input: Value,
26	    },
27	    /// Anthropic server-side tool invocation (e.g. web_search, code_execution).
28	    /// These are executed server-side; jfc renders them but does not dispatch
29	    /// them locally. Shape mirrors `tool_use` but uses `server_tool_use` type.
30	    ServerToolUse {
31	        id: String,
32	        name: String,
33	        input: Value,
34	    },
35	    /// Server-side tool result blocks (`web_search_tool_result`,
36	    /// `code_execution_tool_result`, `tool_search_tool_result`, ...).
37	    /// `tool_kind` preserves the original wire type so future Anthropic
38	    /// result blocks can round-trip without a parser release.
39	    ServerToolResult {
40	        tool_use_id: String,
41	        tool_kind: ServerToolResultKind,
42	        content: Value,
43	    },
44	    Compaction,
45	    /// Forward-compatible catch-all for new content block types. Unknown
46	    /// blocks are ignored unless they carry `tool_use_id` + `content`, in
47	    /// which case they are promoted to `ServerToolResult` above.
48	    Unknown {
49	        kind: String,
50	        raw: Value,
51	    },
