54	impl<'de> Deserialize<'de> for ContentBlock {
55	    fn deserialize<D>(deserializer: D) -> std::result::Result<Self, D::Error>
56	    where
57	        D: serde::Deserializer<'de>,
58	    {
59	        let value = Value::deserialize(deserializer)?;
60	        let kind = value
61	            .get("type")
62	            .and_then(Value::as_str)
63	            .ok_or_else(|| D::Error::missing_field("type"))?
64	            .to_owned();
65	
66	        macro_rules! block {
67	            ($ty:ty) => {
68	                serde_json::from_value::<$ty>(value.clone()).map_err(D::Error::custom)?
69	            };
70	        }
71	
72	        match kind.as_str() {
73	            "text" => {
74	                #[derive(Deserialize)]
75	                struct Block {
76	                    #[serde(default)]
77	                    text: String,
78	                }
79	                let block = block!(Block);
80	                Ok(Self::Text { text: block.text })
81	            }
82	            "thinking" => {
83	                #[derive(Deserialize)]
84	                struct Block {
85	                    #[serde(default)]
86	                    thinking: String,
87	                }
88	                let block = block!(Block);
89	                Ok(Self::Thinking {
90	                    thinking: block.thinking,
91	                })
92	            }
93	            "redacted_thinking" => {
94	                #[derive(Deserialize)]
95	                struct Block {
96	                    data: String,
97	                }
98	                let block = block!(Block);
99	                Ok(Self::RedactedThinking { data: block.data })
100	            }
101	            "tool_use" => {
102	                #[derive(Deserialize)]
103	                struct Block {
104	                    id: String,
105	                    name: String,
106	                    #[serde(default)]
107	                    input: Value,
108	                }
109	                let block = block!(Block);
110	                Ok(Self::ToolUse {
111	                    id: block.id,
112	                    name: block.name,
113	                    input: block.input,
114	                })
115	            }
116	            "server_tool_use" => {
117	                #[derive(Deserialize)]
118	                struct Block {
119	                    id: String,
120	                    name: String,
121	                    #[serde(default)]
122	                    input: Value,
123	                }
124	                let block = block!(Block);
125	                Ok(Self::ServerToolUse {
126	                    id: block.id,
127	                    name: block.name,
128	                    input: block.input,
129	                })
130	            }
131	            "web_search_tool_result"
132	            | "code_execution_tool_result"
133	            | "web_fetch_tool_result"
134	            | "advisor_tool_result"
135	            | "bash_code_execution_tool_result"
136	            | "text_editor_code_execution_tool_result"
137	            | "tool_search_tool_result" => {
138	                #[derive(Deserialize)]
139	                struct Block {
140	                    tool_use_id: String,
141	                    #[serde(default)]
142	                    content: Value,
143	                }
144	                let block = block!(Block);
145	                Ok(Self::ServerToolResult {
146	                    tool_use_id: block.tool_use_id,
147	                    tool_kind: ServerToolResultKind::from_wire_type(&kind),
148	                    content: block.content,
149	                })
150	            }
151	            "compaction" => Ok(Self::Compaction),
152	            _ => {
153	                if let Some(tool_use_id) = value.get("tool_use_id").and_then(Value::as_str) {
154	                    return Ok(Self::ServerToolResult {
155	                        tool_use_id: tool_use_id.to_owned(),
156	                        tool_kind: ServerToolResultKind::from_wire_type(&kind),
157	                        content: value.get("content").cloned().unwrap_or(Value::Null),
158	                    });
159	                }
160	                Ok(Self::Unknown { kind, raw: value })
161	            }
162	        }
163	    }
164	}
